<script setup lang="ts">
import { isDesktopShell } from '../desktop'
import { onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { api, post, message } from '../api'
import { useAuth } from '../auth'
const router = useRouter(), auth = useAuth(), setup = ref(false), loading = ref(false), checking = ref(true), error = ref('')
const form = reactive({ username: '', password: '', setup_key: '' })
async function check() { checking.value = true; error.value = ''; try { setup.value = (await api('/setup')).required; } catch(e) { error.value = message(e) } finally { checking.value = false } }
async function submit() { if (!form.username.trim() || !form.password || (setup.value && !form.setup_key)) { error.value = '请填写完整信息'; return } loading.value = true; error.value = ''; try { if (setup.value) await post('/setup', form); await post('/login', {username:form.username,password:form.password}); form.password=''; form.setup_key=''; await auth.refresh(); router.replace(auth.user?.must_change_password ? '/change-password' : '/instances') } catch(e) { error.value = message(e) } finally { loading.value=false } }
onMounted(check)
</script>
<template><div class="login-page"><div class="login-story"><div class="brand"><div>Toolbox<small>MCP WORKSPACE</small></div></div><div><div class="eyebrow">ONE GATEWAY. ALL YOUR TOOLS.</div><h1>工具集中管理，<br>协作从此有序。</h1><p>连接你的 MCP 服务，为每位成员提供<br>清晰、受控、可追踪的工具访问。</p><div class="login-features"><span>01 统一接入</span><span>02 按需授权</span><span>03 全程追踪</span></div></div><small>企业级 MCP 管理平台</small></div><div class="login-form"><div class="login-card" v-loading="checking"><span class="eyebrow">WELCOME TO TOOLBOX</span><h2>{{ setup ? '初始化工作空间' : '欢迎回来' }}</h2><p>{{ setup ? '使用部署初始化密钥，创建首位管理员。' : '登录你的组织账号，继续管理工具。' }}</p><el-alert v-if="error" :title="error" type="error" :closable="false" show-icon /><el-form @submit.prevent="submit" label-position="top"><el-form-item label="账号"><el-input v-model="form.username" name="username" autocomplete="username" placeholder="输入账号" size="large" /></el-form-item><el-form-item label="密码"><el-input v-model="form.password" type="password" name="password" :autocomplete="setup?'new-password':'current-password'" show-password placeholder="输入密码" size="large" /></el-form-item><el-form-item v-if="setup" label="部署初始化密钥"><el-input v-model="form.setup_key" type="password" name="setup_key" show-password autocomplete="off" placeholder="由部署管理员提供" size="large" /></el-form-item><el-button native-type="submit" type="primary" size="large" :loading="loading" :disabled="checking" class="full-width">{{ setup ? '创建管理员并进入' : '登录工作空间' }}</el-button></el-form><el-button v-if="error" text @click="check">重新检查连接</el-button><p v-if="isDesktopShell()" class="login-note">本地账号独立于企业账号。首次使用：账号 toolbox，初始密码 toolbox@2026，登录后须修改。</p><p v-else class="login-note">账号由管理员创建，不开放公开注册。</p><p v-if="!isDesktopShell()" class="login-note"><router-link to="/download">下载独立本地桌面版</router-link></p></div></div></div></template>
